class CamerasWrapper:
    def __init__(self, cams):
        self._cams_list = []
        if isinstance(cams, dict):
            # 原始 dict：action_name -> handXXXX -> list
            for cam_dict in cams.values():
                if isinstance(cam_dict, dict):
                    for cam_list in cam_dict.values():
                        self._cams_list.extend(cam_list)
                elif isinstance(cam_dict, list):
                    self._cams_list.extend(cam_dict)
        elif isinstance(cams, list):
            # 直接是 list
            self._cams_list.extend(cams)
        else:
            raise ValueError(f"CamerasWrapper 不支持类型: {type(cams)}")
    def __getitem__(self, idx):
        return self._cams_list[idx]
    def __len__(self):
        return len(self._cams_list)


class Human36mDataset(MocapDataset):

    def __init__(self, path, remove_static_joints=True):
        super().__init__(fps=30, skeleton=h36m_skeleton)

        self._cameras = copy.deepcopy(h36m_cameras_extrinsic_params)

        def _parse_entry(entry):
            """统一解析字符串、dict、list"""
            if isinstance(entry, dict):
                return {k: _parse_entry(v) for k, v in entry.items()}
            if isinstance(entry, list):
                return [_parse_entry(e) for e in entry]
            if isinstance(entry, str):
                s = entry.strip()
                # 先尝试 JSON（双引号）
                try:
                    return json.loads(s)
                except Exception:
                    pass
                # 再尝试 Python literal（单引号）
                try:
                    return ast.literal_eval(s)
                except Exception:
                    pass
                # 最后兜底：替换引号再试
                try:
                    return ast.literal_eval(s.replace('"', "'"))
                except Exception as e:
                    raise ValueError(f"相机参数解析失败: {entry}") from e
            return entry  # 其它类型原样返回

        # 递归解析整个结构
        for subject, cameras in self._cameras.items():

            #self._cameras[subject] = _parse_entry(cameras)

            # 遍历到最内层的 dict，应用内参 + 归一化
            # 结构是 {camera_id: [dict, dict, ...]}
            for cam_id, cam_list in self._cameras[subject].items():
                if not isinstance(cam_list, list):
                    raise ValueError(f"subject {subject} 相机 {cam_id} 不是 list: {type(cam_list)}")

                for i, cam in enumerate(cam_list):
                    cam.update(h36m_cameras_intrinsic_params[i])
                    for k, v in list(cam.items()):
                        if k not in ['id', 'res_w', 'res_h']:
                            cam[k] = np.array(v, dtype='float32')

                    # Normalize camera frame
                    cam['center'] = normalize_screen_coordinates(
                        cam['center'], w=cam['res_w'], h=cam['res_h']
                    ).astype('float32')
                    cam['focal_length'] = cam['focal_length'] / cam['res_w'] * 2
                    if 'translation' in cam:
                        cam['translation'] = cam['translation'] / 1000  # mm → m

                    # Add intrinsic parameters vector
                    cam['intrinsic'] = np.concatenate((
                        cam['focal_length'],
                        cam['center'],
                        cam['radial_distortion'],
                        cam['tangential_distortion'],
                        [1 / cam['focal_length'][0], 0,
                         -cam['center'][0] / cam['focal_length'][0],
                         0, 1 / cam['focal_length'][1],
                         -cam['center'][1] / cam['focal_length'][1],
                         0, 0, 1]
                    ))
                # proj_matrix = np.array([1/cam['focal_length'][0], 0, -cam['center'][0]/cam['focal_length'][0],
                #                         0, 1/cam['focal_length'][1], -cam['center'][1]/cam['focal_length'][1],
                #                         0, 0, 1])
                # cam['intrinsic'] = np.concatenate(camera_intrinsics, proj_matrix)

        # Load serialized dataset

        data = np.load(path, allow_pickle=True)['positions_3d'].item()

        self._data = {}
        for subject, actions in data.items():
            self._data[subject] = {}
            for action_name, positions in actions.items():
                self._data[subject][action_name] = {
                    'positions': positions,
                    'cameras': self._cameras[subject][action_name],
                }
        for subject, actions in self._data.items():
            for action_name, anim in actions.items():
                anim['cameras_list'] = []  # 初始化空列表
                if isinstance(anim['cameras'], dict):
                    # anim['cameras'] 是 dict（hand0101 -> list）
                    for cam_list in anim['cameras'].values():
                        anim['cameras_list'].extend(cam_list)
                elif isinstance(anim['cameras'], list):
                    # anim['cameras'] 本身就是 list
                    anim['cameras_list'].extend(anim['cameras'])
                else:
                    raise ValueError(f"anim['cameras'] 类型不支持: {type(anim['cameras'])}")
        for subject in self._cameras.keys():
            self._cameras[subject] = CamerasWrapper(self._cameras[subject])
        #if remove_static_joints:
            # Bring the skeleton to 17 joints instead of the original 32
       #     self.remove_joints([4, 5, 9, 10, 11, 16, 20, 21, 22, 23, 24, 28, 29, 30, 31])

            # Rewire shoulders to the correct parents
        #    self._skeleton._parents[11] = 8
        #    self._skeleton._parents[14] = 8

    def supports_semi_supervised(self):
        return True